/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var View = require( '@stdlib/plot/base/view' );


// VARIABLES //

var debug = logger( 'plot:view' );


// MAIN //

/**
* Creates a plot view.
*
* @private
* @param {string} [viewer] - plot viewer
*/
function view( viewer ) {
	var view;
	var v;

	if ( arguments.length ) {
		v = viewer;
	} else {
		v = this.viewer;
	}
	debug( 'Viewer: %s', v );

	view = new View( this );
	view.render( v );
}


// EXPORTS //

module.exports = view;
